frappe.ui.form.on('Task', {
    refresh: function(frm) {
        // Скрываем область ссылок в дашборде
        if (frm.dashboard && frm.dashboard.links_area) {
            frm.dashboard.links_area.hide();
        }

        // Добавляем кнопку только если это существующая задача (не новая)
        if (!frm.is_new()) {
            frm.add_custom_button(__('Создать подзадачу'), function() {
                // Создаем новую задачу с предзаполненными полями
                frappe.new_doc('Task', {
                    project: frm.doc.project,
                    parent_task: frm.doc.name
                });
            }).addClass('btn-primary');
        }
    }
});
